import {controlConclusion} from './research.js?v=20261114.6';
import {contextualPrompt} from './risk-intelligence.js?v=20261114.6';
import {esc,icon,button,link,sourceLink} from './ui.js?v=20261114.6';
import {controlsLibrary,mappingApplicability,mappingNeedsReview} from './mappings.js?v=20261114.6';

const locked=s=>s.role!=='first'||s.submitted;
const disabled=s=>locked(s)?'disabled':'';
const proposed=c=>String(c.status||'').toLowerCase()==='proposed'||c.proposed===true;
const library=(data,s)=>controlsLibrary(data,s);
const find=(data,s,id)=>library(data,s).find(c=>c.id===id);
const action=(text,name,s,attrs='',primary=false)=>button(text,name,`class="button ${primary?'primary':''}" ${disabled(s)} ${attrs}`);
function svgLines(text,x,y,width=25){
  const words=String(text).split(/\s+/),lines=[''];
  for(const word of words){if((lines.at(-1)+' '+word).trim().length>width)lines.push(word);else lines[lines.length-1]=(lines.at(-1)+' '+word).trim();}
  return `<text x="${x}" y="${y}" class="cm-node-title">${lines.slice(0,3).map((l,i)=>`<tspan x="${x}" dy="${i?19:0}">${esc(l)}</tspan>`).join('')}</text>`;
}
function network(r,controls,shared,judgment=''){
  const h=Math.max(240,controls.length*110+30),middle=h/2,ys=controls.map((_,i)=>i*110+28),key=esc(r.id).replace(/[^a-z0-9-]/gi,'');
  return `<div class="cm-network" role="group" aria-label="Control relationships"><svg viewBox="0 0 ${shared?970:740} ${h}" role="img" aria-labelledby="cm-title-${key} cm-desc-${key}"><title id="cm-title-${key}">Controls mapped to ${esc(r.name)}</title><desc id="cm-desc-${key}">${controls.map(c=>`${esc(c.name)} is ${proposed(c)?'proposed and not implemented':'mapped'}`).join('. ')}.${shared?(judgment==='confirmed'?' The owner confirmed the shared customer-contact record.':judgment==='dismissed'?' The owner dismissed the suggested shared customer-contact record.':' The procedures suggest a possible shared customer-contact record; no unqualified conclusion is recorded.'):''}</desc><defs><marker id="cm-arrow-${key}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs>
  ${controls.map((c,i)=>`<path class="cm-edge ${proposed(c)?'is-proposed':''}" d="M232 ${middle} H265 Q280 ${middle} 280 ${middle+(ys[i]+42>middle?15:-15)} V${ys[i]+42} H323" marker-end="url(#cm-arrow-${key})"/>${shared&&['callback','approval'].includes(c.id)?`<path class="cm-edge cm-edge-source" d="M590 ${ys[i]+42} H635 Q650 ${ys[i]+42} 650 ${ys[i]+42+(middle>ys[i]+42?15:-15)} V${middle} H709" marker-end="url(#cm-arrow-${key})"/>`:''}`).join('')}
  <rect x="16" y="${middle-48}" width="216" height="96" rx="9" class="cm-risk-node"/><text x="34" y="${middle-25}" class="cm-node-label">RISK</text>${svgLines(r.name,34,middle-3,25)}
  ${controls.map((c,i)=>`<g><rect x="323" y="${ys[i]}" width="267" height="86" rx="9" class="cm-control-node ${proposed(c)?'is-proposed':''}"/><text x="341" y="${ys[i]+20}" class="cm-node-label">${proposed(c)?'PROPOSED · NOT IMPLEMENTED':'MAPPED CONTROL'}</text>${svgLines(c.name,341,ys[i]+44,29)}</g>`).join('')}
  ${shared?`<rect x="710" y="${middle-48}" width="244" height="96" rx="9" class="cm-source-node"/><text x="728" y="${middle-25}" class="cm-node-label">${judgment==='confirmed'?'CONFIRMED SHARED SOURCE':judgment==='dismissed'?'SUGGESTION DISMISSED':'POSSIBLE SHARED SOURCE'}</text>${svgLines('Customer-contact record',728,middle-2,26)}<text x="728" y="${middle+30}" class="cm-node-meta">${judgment==='confirmed'?'Used by 2 controls':judgment==='dismissed'?'No dependency conclusion':judgment==='qualified'?'Owner qualification recorded':'Owner judgment needed'}</text>`:''}</svg></div>${mobileNetwork(r,controls,shared,judgment)}`;
}
function mobileNetwork(r,controls,shared,judgment){
  return `<div class="cm-network-mobile" aria-label="Control relationships"><div class="cm-mobile-node cm-mobile-risk"><span>Risk</span><strong>${esc(r.name)}</strong></div><div class="cm-mobile-connector" aria-hidden="true">${icon('arrow',17)}</div><div class="cm-mobile-controls">${controls.map(c=>`<div class="cm-mobile-node cm-mobile-control ${proposed(c)?'is-proposed':''}"><span>${proposed(c)?'Proposed · not implemented':'Mapped control'}</span><strong>${esc(c.name)}</strong></div>`).join('')}</div>${shared?`<div class="cm-mobile-connector" aria-hidden="true">${icon('arrow',17)}</div><div class="cm-mobile-node cm-mobile-source"><span>${judgment==='confirmed'?'Confirmed shared source':judgment==='dismissed'?'Suggestion dismissed':'Possible shared source'}</span><strong>Customer-contact record</strong><small>${judgment==='confirmed'?'Used by callback verification and supervisory approval':judgment==='dismissed'?'No dependency conclusion is recorded':judgment==='qualified'?'Owner qualification recorded':'Owner judgment needed'}</small></div>`:''}</div>`;
}
function controlRow(data,s,r,c){
  const p=proposed(c),rationale=r.mappingRationale?.[c.id]||c.purpose||'',conclusion=mappingApplicability(data,s,r.id,c.id).conclusion;
  const coverage=conclusion==='prepared'?(c.designConclusion||'Prepared coverage assessment retained.'):conclusion==='covers'?(p?'Owner expects the proposed design to address this risk.':'Owner expects the design to address this risk.'):conclusion==='limited'?'Owner assessed limited coverage for this risk.':conclusion==='none'?'Owner assessed no current coverage for this risk.':'Coverage/applicability requires owner assessment.';
  return `<tr role="row" class="${s.selectedControl===c.id?'cm-selected-row':''}"><td role="cell">${button(esc(c.name),'control',`class="cm-control-link" data-control="${esc(c.id)}" aria-pressed="${s.selectedControl===c.id}"`)}<small>${esc(c.owner)}</small>${p?'<span class="cm-proposed">Proposed · not implemented</span>':''}</td><td role="cell" data-label="Coverage rationale"><p>${esc(rationale)}</p></td><td role="cell" data-label="Coverage assessment and evidence"><span class="cm-table-label">Risk coverage · ${conclusion==='prepared'?'prepared assessment':'owner judgment'}</span><p class="${conclusion==='unassessed'?'cm-coverage-pending':''}">${esc(coverage)}</p><span class="cm-table-label">${p?'Current operation':'Library result'}</span><p>${esc(p?'Not implemented or tested. No current protection established.':c.operation||c.evidence||'No operating evidence recorded.')}</p>${!p?testScope(data,c):''}</td><td role="cell" data-label="Mapping actions"><div class="cm-row-actions">${action('Edit mapping','mapping-edit',s,`data-control="${esc(c.id)}"`)}${action('Replace','mapping-replace',s,`data-control="${esc(c.id)}"`)}${action('Remove','mapping-remove-review',s,`data-control="${esc(c.id)}"`)}</div></td></tr>`;
}
function testScope(data,c){
  const test=data.sources.find(source=>source.id===c.test);
  return `<small class="cm-test-scope">${esc(test?`${test.scope} · ${test.date}`:'No test population or period recorded.')}</small>`;
}
export function controlsWorkspace(data,s){
  const r=s.risks[s.selectedRisk],controls=(r.controls||[]).map(id=>find(data,s,id)).filter(Boolean),shared=r.controls?.includes('callback')&&r.controls?.includes('approval');
  const c=controls.find(c=>c.id===s.selectedControl)||controls[0],readonly=locked(s);
  const mappedSuggestion=controls.find(c=>proposed(c)&&String(c.name).trim().toLowerCase()==='independent contact verification');
  return `<section class="cm-workspace"><header class="cm-heading"><div><h1>Build a clear picture of protection.</h1><p>Map the controls, inspect their evidence, and understand what they support.</p></div>${readonly?button(s.role==='first'?'Start owner revision':'Browse control library',s.role==='first'?'owner-revision':'control-library','class="button primary"'):action(`${icon('source',17)} Map a control`,'mapping-add',s,'',true)}</header>
  ${s.submitted?`<div class="cm-version-note"><span>Version ${s.versionNumber} · ${s.reviewed?'Reviewed':'In review'}. ${s.role==='first'?'Start an owner revision to change mappings.':`Control changes belong to ${esc(data.owner)}.`}</span>${button('Inspect submitted version','version',`class="text-link" data-version="${s.versionNumber}"`)}</div>`:s.revisionOf?`<div class="cm-version-note"><span>Owner revision · based on version ${s.revisionOf}</span>${button('Inspect prior version','version',`class="text-link" data-version="${s.revisionOf}"`)}</div>`:''}
  <nav class="cm-risks" aria-label="Risk under assessment">${Object.values(s.risks).map(x=>button(esc(x.name),'risk',`class="cm-risk-tab ${r.id===x.id?'selected':''}" data-risk="${esc(x.id)}" aria-pressed="${r.id===x.id}"`)).join('')}</nav>
  <div class="cm-layout"><section class="sheet cm-main"><div class="cm-section-heading"><div><span class="label">${esc(r.name)}</span><h2>Control mapping</h2></div><span class="cm-count">${controls.length} mapped</span></div>
  ${controls.length?network(r,controls,shared,s.dependency):`<div class="cm-empty">${icon('source',30)}<h3>No controls mapped yet.</h3><p>Choose an existing control or propose one. An unmapped risk needs an explicit owner conclusion.</p>${action('Map the first control','mapping-add',s,'',true)}</div>`}
  ${shared?`<div class="cm-finding"><div>${icon('info',19)}</div><p><strong>${s.dependency==='confirmed'?'Shared source confirmed':s.dependency==='qualified'?'Qualified source relationship':s.dependency==='dismissed'?'Source suggestion dismissed':'A relationship to inspect'}</strong><span>${s.dependency==='confirmed'?'You confirmed that callback verification and supervisory approval consult the same contact record.':s.dependency==='dismissed'?'You dismissed the suggested dependency. No shared-source conclusion is recorded.':s.dependency==='qualified'?`The possible relationship is qualified: ${esc(s.qualification)}`:'The procedures suggest that both checks may consult the same contact record. Owner judgment is needed.'}</span></p>${link('Inspect evidence','navigate','data-route="assessment/discovery"')}</div>`:''}
  ${controls.length?`<details class="cm-mapping-fold" data-edit="mappings" ${s.editPanels?.mappings||mappingNeedsReview(data,s,r.id)?'open':''}><summary>Inspect mapped controls (${controls.length}) and edit mappings</summary><div class="cm-mappings"><h3>Mapped controls <span>(${controls.length})</span></h3><p class="muted small">Risk coverage is an owner judgment. Library results support only their recorded population and period.</p>${mappingNeedsReview(data,s,r.id)?'<p class="cm-coverage-notice" role="status">Assess each new relationship before confirming controls. Use <strong>Edit mapping</strong> to record your coverage judgment.</p>':''}<div class="cm-table-scroll"><table class="cm-table" role="table" aria-label="Mapped controls"><thead><tr><th scope="col">Control</th><th scope="col">Coverage rationale</th><th scope="col">Coverage & evidence</th><th scope="col">Mapping</th></tr></thead><tbody>${controls.map(c=>controlRow(data,s,r,c)).join('')}</tbody></table></div></div></details>`:''}
  ${c?`<details class="cm-evidence"><summary>Inspect ${esc(c.name)}</summary><p>${esc(c.design)}</p><p><strong>${proposed(c)?'Operating evidence':'Library operating evidence'}:</strong> ${esc(proposed(c)?'No implementation or test evidence has been recorded.':c.evidence)}</p>${!proposed(c)?testScope(data,c):''}<div class="button-group">${c.source?sourceLink(proposed(c)?'Suggestion basis':'Control description',c.source):''}${c.test&&!proposed(c)?sourceLink('Test scope',c.test):''}</div></details>`:''}
  ${controlConclusion(data,s)}${!controls.length?`<label class="attestation cm-empty-attest"><input id="no-controls-attest" type="checkbox" ${r.noControlsConfirmed?'checked':''} ${readonly?'disabled':''}> I confirm that no controls are currently mapped and will reflect this in the assessment.</label>`:''}</section>
  <aside class="sheet cm-assistance"><span class="attribution">AI-assisted mapping</span><h2>${r.id==='unauthorized'?(mappedSuggestion?'Proposed control mapped.':'One useful addition to review.'):'Find a relevant control.'}</h2><p class="muted">${mappedSuggestion?'Review the proposed design and its coverage rationale. Implementation and operating evidence are still required.':'A suggestion starts a review. Your confirmation establishes the mapping.'}</p>
  ${r.id==='unauthorized'?`<div class="cm-suggestion"><span class="cm-proposed">Proposed · not implemented</span><h3>Independent contact verification</h3><p>Consider whether an independently verified contact source would address the exposure from recently amended contact details.</p><dl><div><dt>Basis</dt><dd>October 20 near miss and the documented verification process</dd></div><div><dt>Current limitation</dt><dd>A proposed control provides no current protection or operating evidence.</dd></div></dl>${sourceLink('Inspect the near miss','incident')}${mappedSuggestion?button('Inspect proposed control','control',`class="button primary" data-control="${esc(mappedSuggestion.id)}"`):action('Review suggestion','mapping-ai-draft',s,'',true)}</div>`:`<div class="cm-suggestion"><h3>Start with the control library.</h3><p>Compare the control objective with this risk and explain the protection it is expected to provide.</p></div>`}
  ${button('Browse control library','control-library','class="button"')}<p class="cm-boundary">Mapping or removing a control does not change a risk rating.</p></aside></div>
  ${contextualPrompt(data,s,'controls')}<div class="step-footer">${link('Back to inherent risk','navigate','data-route="assessment/inherent"')}${readonly?'<span class="quiet-status">Assessment record · read-only</span>':action(`${shared?'Confirm controls and inspect connection':'Confirm control assessment'} ${icon('arrow',16)}`,'confirm-controls',s,'',true)}</div></section>`;
}
function dialogField(label,key,value,{area=false,required=true,readOnly=false}={}){
  return `<label class="field" for="mapping-${key}"><span>${esc(label)}</span>${area?`<textarea id="mapping-${key}" name="mapping-${key}" data-field="mapping.${key}" aria-label="${esc(label)}" rows="3" ${readOnly?'readonly':''} ${required?'required':''}>${esc(value)}</textarea>`:`<input id="mapping-${key}" name="mapping-${key}" data-field="mapping.${key}" aria-label="${esc(label)}" value="${esc(value)}" ${readOnly?'readonly':''} ${required?'required':''}>`}</label>`;
}
export function mappingDialog(data,s,{mode='add',controlId=''}={}){
  const r=s.risks[s.selectedRisk],draft=s.mappingDraft||{},editing=mode==='edit',replacing=mode==='replace',c=find(data,s,controlId),tab=draft.mode==='create'?'create':'existing';
  const choices=library(data,s).filter(c=>!r.controls.includes(c.id)), access={readOnly:locked(s)};
  const selected=draft.controlId||choices[0]?.id||'';
  const rationale=draft.rationale??(editing?r.mappingRationale?.[controlId]||c?.purpose||'':'');
  const current=editing?mappingApplicability(data,s,r.id,controlId).conclusion:'unassessed',applicability=draft.applicability??current;
  return `<div class="cm-mapping-dialog"><span class="label">${esc(r.name)}</span><h2 id="dialog-title">${editing?'Assess this control’s coverage.':replacing?'Replace this mapping.':'Map a control.'}</h2><p>${editing?'Explain this control’s coverage for this risk. The shared control definition stays unchanged.':replacing?`Choose a replacement for ${esc(c?.name||'the selected control')}. The change is recorded together when you save.`:'Use a control already in the library, or propose a new one.'}</p>
  ${editing?`<div class="cm-dialog-current"><strong>${esc(c?.name)}</strong><span>${esc(c?.owner)}</span></div>`:`<div class="cm-dialog-tabs" role="group" aria-label="Control mapping approach">${button('Existing control','mapping-mode',`class="button ${tab==='existing'?'primary':''}" data-mode="existing" aria-pressed="${tab==='existing'}" ${disabled(s)}`)}${button('Create a control','mapping-mode',`class="button ${tab==='create'?'primary':''}" data-mode="create" aria-pressed="${tab==='create'}" ${disabled(s)}`)}</div>`}
  ${!editing&&tab==='existing'?`<label class="field" for="mapping-control"><span>Control from the library</span><select id="mapping-control" name="mapping-control" aria-label="Control from the library" data-field="mapping.controlId" ${!choices.length||locked(s)?'disabled':''}>${choices.length?choices.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}${proposed(x)?' · Proposed':''}</option>`).join(''):'<option value="">All available controls are already mapped</option>'}</select></label>${!choices.length?'<p class="cm-dialog-note">Create a proposed control, or return to edit an existing mapping.</p>':''}`:''}
  ${!editing&&tab==='create'?`<p class="cm-proposed">New controls start as proposed, not implemented.</p>${dialogField('Control name','name',draft.name||'',access)}${dialogField('Accountable owner','owner',draft.owner||'',access)}${dialogField('Control objective','purpose',draft.purpose||'',access)}${dialogField('Proposed design','design',draft.design||'',{...access,area:true})}`:''}
  ${dialogField('Coverage rationale for this risk','rationale',rationale,{...access,area:true})}<p class="cm-dialog-note">Describe the risk or cause addressed and any limits to the expected coverage.</p>
  <label class="field" for="mapping-applicability"><span>Owner coverage assessment</span><select id="mapping-applicability" aria-label="Owner coverage assessment" name="mapping-applicability" data-field="mapping.applicability" aria-describedby="mapping-coverage-note" ${disabled(s)}>${[...(current==='prepared'?[['prepared','Keep the prepared assessment']]:[]),['unassessed','Not yet assessed'],['covers','Design is expected to address this risk'],['limited','Limited coverage for this risk'],['none','No current coverage for this risk']].map(([value,label])=>`<option value="${value}" ${applicability===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><p id="mapping-coverage-note" class="cm-dialog-note">Record your risk-specific judgment, or leave it unassessed for later review. A coverage judgment does not establish implementation or operating effectiveness. Proposed controls provide no current protection.</p>
  <div class="button-group">${action(editing?'Save mapping':replacing?'Replace mapping':tab==='create'?'Create and map proposed control':'Map selected control','mapping-save',s,`data-operation="${mode}" data-mode="${editing?'edit':tab}" data-control="${esc(controlId)}" ${!editing&&tab==='existing'&&!choices.length?'disabled':''}`,true)}${button('Cancel','close-dialog','class="button quiet"')}</div></div>`;
}
export function removalDialog(data,s,controlId){
  const r=s.risks[s.selectedRisk],c=find(data,s,controlId);
  return `<div class="cm-mapping-dialog"><span class="label">${esc(r.name)}</span><h2 id="dialog-title">Remove this mapping?</h2><p><strong>${esc(c?.name||'This control')}</strong> will no longer be mapped to this risk. Its definition and mappings to other risks are retained.</p><p class="cm-dialog-note">Review the remaining coverage and reconfirm the control assessment. Risk ratings stay unchanged until you assess them.</p><div class="button-group">${action('Remove mapping','mapping-remove',s,`data-control="${esc(controlId)}"`,true)}${button('Keep mapping','close-dialog','class="button"')}</div></div>`;
}
